#include <cstddef>
#include <utility>
class Buffer {
    int*   data_ = nullptr;
    size_t size_ = 0;
public:
    Buffer() = default;
    explicit Buffer(size_t n) : data_(new int[n]), size_(n) {}
    ~Buffer() { delete[] data_; }

    // Move constructor: steal resources, leave source empty.
    Buffer(Buffer&& other) noexcept
        : data_(other.data_), size_(other.size_) {
        other.data_ = nullptr;
        other.size_ = 0;
    }

    // Move assignment: free ours, guard self-assign, steal, null source.
    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            data_ = other.data_;
            size_ = other.size_;
            other.data_ = nullptr;
            other.size_ = 0;
        }
        return *this;
    }

    // (Copy ops omitted; delete or implement per rule of five.)
    Buffer(const Buffer&) = delete;
    Buffer& operator=(const Buffer&) = delete;
};

#include <cstring>
#include <utility>
#include <cstddef>

class Buffer {
public:
    explicit Buffer(size_t n = 0) : size_(n), data_(n ? new char[n] : nullptr) {}
    ~Buffer() { delete[] data_; }

    Buffer(const Buffer& o) : size_(o.size_), data_(o.size_ ? new char[o.size_] : nullptr) {
        if (size_) std::memcpy(data_, o.data_, size_);          // deep copy
    }
    Buffer& operator=(const Buffer& o) {                         // copy-and-swap
        Buffer tmp(o); swap(*this, tmp); return *this;
    }

    Buffer(Buffer&& o) noexcept : size_(o.size_), data_(o.data_) { // steal
        o.data_ = nullptr; o.size_ = 0;                          // leave source empty/valid
    }
    Buffer& operator=(Buffer&& o) noexcept {
        if (this != &o) { delete[] data_; data_ = o.data_; size_ = o.size_; o.data_ = nullptr; o.size_ = 0; }
        return *this;
    }
    friend void swap(Buffer& a, Buffer& b) noexcept {
        std::swap(a.size_, b.size_); std::swap(a.data_, b.data_);
    }
private:
    size_t size_ = 0;
    char*  data_ = nullptr;
};
// noexcept moves => std::vector<Buffer> MOVES (not copies) elements when it grows.
